{
  "name": "opencarly",
  "version": "1.0.3",
  "type": "module",
  "description": "Context Augmentation & Reinforcement Layer for OpenCode - Dynamic rules that load when relevant, disappear when not.",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "bin": {
    "opencarly": "bin/install.cjs"
  },
  "files": [
    "dist",
    "bin",
    "templates",
    "commands"
  ],
  "scripts": {
    "build": "tsc",
    "dev": "tsc --watch",
    "typecheck": "tsc --noEmit",
    "prepublishOnly": "npm run build"
  },
  "dependencies": {
    "minimatch": "^10.2.4",
    "zod": "^3.23.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.0.0",
    "@types/minimatch": "^5.1.2",
    "@types/node": "^22.0.0",
    "typescript": "^5.7.0"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "carly",
    "carl",
    "context",
    "rules",
    "dynamic-rules",
    "prompt-engineering",
    "ai",
    "coding-agent"
  ],
  "author": "Blainexi",
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Blainexi/OpenCarly.git"
  },
  "bugs": {
    "url": "https://github.com/Blainexi/OpenCarly/issues"
  },
  "homepage": "https://github.com/Blainexi/OpenCarly#readme",
  "engines": {
    "node": ">=18.0.0"
  }
}
